insert into public.topics (module_id, slug, title, summary, position, published) select id, 'backend-development-concepts', 'Backend Development Concepts', 'What a backend does: requests, responses, routes and business rules.', 0, true from public.modules where level_id = 3 and title = 'Backend & Databases' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain backend development concepts in your own words.","Recognise and apply: an API route receives a request, validates it, does the work, returns a response.","Recognise and apply: never trust the client: re-check auth, roles and rules on the server.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers backend development concepts: what a backend does: requests, responses, routes and business rules. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that an API route receives a request, validates it, does the work, returns a response. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that never trust the client: re-check auth, roles and rules on the server. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how backend development concepts fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'typescript', '// POST /api/redeem-code
