insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain node.js fundamentals in your own words.","Recognise and apply: Node runs JavaScript outside the browser, with file and network access.","Recognise and apply: npm installs versioned packages; package.json records them.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers node.js fundamentals: the Node runtime, modules, npm and the event loop on the server. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that Node runs JavaScript outside the browser, with file and network access. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that npm installs versioned packages; package.json records them. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how node.js fundamentals fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'import { createHash } from ''node:crypto'';
