insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain sql and postgresql in your own words.","Recognise and apply: SELECT ... WHERE filters rows; JOIN combines related tables.","Recognise and apply: a unique constraint is the database''s last line of defence against duplicates.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers sql and postgresql: writing correct SQL: SELECT, WHERE, JOIN, INSERT, UPDATE and constraints. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that SELECT ... WHERE filters rows; JOIN combines related tables. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that a unique constraint is the database''s last line of defence against duplicates. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how sql and postgresql fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'sql', 'SELECT p.full_name, c.title
