insert into public.topics (module_id, slug, title, summary, position, published) select id, 'database-security-and-rls', 'Database Security and RLS', 'Row Level Security policies that make the database enforce who sees what.', 0, true from public.modules where level_id = 3 and title = 'Auth, Security & Supabase' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain database security and rls in your own words.","Recognise and apply: RLS off means any key can read the table; RLS on with no policy means nobody can.","Recognise and apply: a policy like auth.uid() = student_id lets a student see only their own rows.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers database security and rls: Row Level Security policies that make the database enforce who sees what. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that RLS off means any key can read the table; RLS on with no policy means nobody can. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that a policy like auth.uid() = student_id lets a student see only their own rows. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how database security and rls fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'sql', 'ALTER TABLE lesson_progress ENABLE ROW LEVEL SECURITY;
