insert into public.topics (module_id, slug, title, summary, position, published) select id, 'environment-variables', 'Environment Variables', 'Keeping secrets out of source code and in server env vars.', 0, true from public.modules where level_id = 3 and title = 'Auth, Security & Supabase' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain environment variables in your own words.","Recognise and apply: a NEXT_PUBLIC_ variable is shipped to the browser — never put a secret in one.","Recognise and apply: service-role keys live only in server env vars and are never committed.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers environment variables: keeping secrets out of source code and in server env vars. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that a NEXT_PUBLIC_ variable is shipped to the browser — never put a secret in one. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that service-role keys live only in server env vars and are never committed. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how environment variables fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'bash', '# .env.local (never committed)
